 public static void main(String[] args){OlmMechanicAdapter.Config installed=new OlmMechanicAdapter.Config();check(OlmMechanicAdapter.underfootObject(installed,30033)&&OlmMechanicAdapter.underfootObject(installed,30034),"installed crystal objects enabled without manual mapping");check(OlmMechanicAdapter.fallingProjectile(installed,1357)&&OlmMechanicAdapter.fallingGraphic(installed,1352),"installed falling signals enabled");check(!OlmMechanicAdapter.underfootObject(installed,30028),"loot chest is not a crystal");check(OlmMechanicAdapter.namedFlame(installed,"Flame")&&!OlmMechanicAdapter.namedFlame(installed,"Fire giant"),"named flame walls exclude unrelated NPCs");installed.useInstalledCrystalSignals=false;check(!OlmMechanicAdapter.fallingProjectile(installed,1357),"installed mapping can be disabled");
  check(OlmSpecials.prayer(OlmSpecials.Orb.PURPLE)==Prayer.PROTECT_FROM_MAGIC,"purple orb");check(OlmSpecials.prayer(OlmSpecials.Orb.RED)==Prayer.PROTECT_FROM_MELEE,"red orb");check(OlmSpecials.prayer(OlmSpecials.Orb.GREEN)==Prayer.PROTECT_FROM_MISSILES,"green orb");
  OlmSpecials p=new OlmSpecials();OlmSpecials.View v=view();v.hazards.add(new OlmSpecials.Hazard(c(0,0),OlmSpecials.HazardKind.UNDERFOOT,0));OlmSpecials.Choice dodge=p.choose(v);check(dodge.kind==OlmSpecials.Kind.MOVE&&p.safe(dodge.cell,v),"underfoot crystal triggers safe movement");
  p.requested(dodge,v.player,1);p.observe(dodge.cell,2);String learned=p.exportLearning();check(learned.contains("\"reached\":1"),"actual arrival creates positive movement outcome");p.feedback(false);check(p.exportLearning().contains("\"reached\":0"),"explicit correction changes movement preference");OlmSpecials.Choice corrected=p.choose(v);check(!corrected.cell.equals(dodge.cell),"corrected direction loses preference");
  v.hazards.add(new OlmSpecials.Hazard(corrected.cell,OlmSpecials.HazardKind.FALLING,0));OlmSpecials.Choice safe=p.choose(v);check(!safe.cell.equals(corrected.cell),"learned preferences cannot override danger exclusion");v.reachable.clear();check(p.choose(v).kind==OlmSpecials.Kind.HOLD,"no safe route waits without shutting down observer");
  OlmSpecials restored=new OlmSpecials();restored.restoreLearning(learned);check(restored.exportLearning().contains("\"reached\":1"),"learning save/load roundtrip");boolean bad=false;try{restored.restoreLearning("{\"schema\":\"olm-movement-learning-v1\",\"scores\":{\"FALLING:1:0\":{\"attempts\":1,\"reached\":2}}}");}catch(IllegalArgumentException e){bad=true;}check(bad&&restored.exportLearning().contains("\"reached\":1"),"invalid learning rejected atomically");
  p=new OlmSpecials();v=view();v.tickWalking=true;v.attackDue=false;check(p.choose(v).kind==OlmSpecials.Kind.MOVE,"walk between attacks during falling crystals");v.attackDue=true;check(p.choose(v).kind==OlmSpecials.Kind.NONE,"leave attack opportunity available");v.hazards.add(new OlmSpecials.Hazard(v.player,OlmSpecials.HazardKind.FALLING,0));check(p.choose(v).kind==OlmSpecials.Kind.MOVE,"urgent crystal avoidance precedes DPS");
  p=new OlmSpecials();v=view();v.needsApproach=true;OlmSpecials.Choice approach=p.choose(v);check(approach.kind==OlmSpecials.Kind.MOVE&&approach.cell.distance(v.target)<v.player.distance(v.target),"known hazards use safe approach rather than automatic chase");
  p=new OlmSpecials();v=view();v.target=c(0,0);for(int x=-1;x<=1;x++){v.walls.add(c(x,1));v.walls.add(c(x,-1));}OlmSpecials.Choice breakWall=p.choose(v);check(breakWall.kind==OlmSpecials.Kind.BREAK_WALL,"trapped player requests gap creation");p.wallRequested(v.tick);v.tick=2;check(p.choose(v).kind==OlmSpecials.Kind.HOLD,"casting does not fabricate a gap");
  v.walls.remove(breakWall.cell);v.reachable.clear();v.reachable.add(breakWall.cell);OlmSpecials.Choice through=p.choose(v);check(through.kind==OlmSpecials.Kind.MOVE&&through.cell.equals(breakWall.cell),"walk through observed gap");v.player=through.cell;v.reachable.clear();v.reachable.add(c(0,2));check(p.choose(v).cell.equals(c(0,2)),"walk beyond wall line");
  v.player=c(0,2);v.tickWalking=true;v.attackDue=false;v.reachable.clear();v.reachable.add(c(0,1));v.reachable.add(c(0,3));check(p.choose(v).cell.equals(c(0,3))&&!p.holdingOutside(),"continue to two-tile wall clearance before holding");v.player=c(0,3);v.tickWalking=false;check(p.choose(v).kind==OlmSpecials.Kind.NONE&&p.holdingOutside(),"stay outside until wall despawns");v.tickWalking=true;v.walls.clear();v.tick+=2;p.choose(v);v.tick+=2;check(p.choose(v).cell.equals(c(0,1))&&!p.holdingOutside(),"wall despawn releases escape restriction");
  p=new OlmSpecials();v=view();for(int x=-1;x<=1;x++){v.walls.add(c(x,2));v.walls.add(c(x,-2));}check(p.choose(v).kind==OlmSpecials.Kind.MOVE,"flame walls two tiles away trigger approach instead of being ignored");
  p=new OlmSpecials();v=view();v.fireBias=c(0,-20);for(int x=-1;x<=1;x++){v.walls.add(c(x,1));v.walls.add(c(x,-1));}OlmSpecials.Choice biasedWall=p.choose(v);check(biasedWall.kind==OlmSpecials.Kind.BREAK_WALL&&biasedWall.cell.equals(c(0,-1)),"final magic finish opens the flame-wall side nearest the melee-hand/right-side bias");
  p=new OlmSpecials();v=view();for(int x=-1;x<=1;x++){v.walls.add(c(x,1));v.walls.add(c(x,-1));}breakWall=p.choose(v);v.walls.remove(breakWall.cell);v.reachable.clear();for(int y=1;y<=4;y++)v.reachable.add(c(0,y));check(p.choose(v).cell.equals(c(0,4)),"opened north gap selects one click three tiles beyond the wall");v.hazards.add(new OlmSpecials.Hazard(c(0,4),OlmSpecials.HazardKind.ELECTRIC,0));check(p.choose(v).cell.equals(c(0,3)),"unsafe three-tile clearance falls back to safe two-tile clearance");v.player=c(0,2);check(p.choose(v).cell.equals(c(0,3))&&!p.holdingOutside(),"one tile beyond the wall does not finish escape prematurely");v.player=c(0,3);v.hazards.clear();v.tickWalking=false;v.needsApproach=false;check(p.choose(v).kind==OlmSpecials.Kind.NONE&&p.holdingOutside(),"observed two-tile clearance completes escape without more movement");
  OlmMechanicAdapter.Config cfg=new OlmMechanicAdapter.Config();cfg.validate();cfg.wallMode=OlmMechanicAdapter.WallMode.CLICK;bad=false;try{cfg.validate();}catch(IllegalArgumentException e){bad=true;}check(bad,"uncalibrated wall interaction rejected");
  cfg=new OlmMechanicAdapter.Config();cfg.maxStep=3;bad=false;try{cfg.validate();}catch(IllegalArgumentException e){bad=true;}check(bad,"unsupported movement geometry rejected");
  p=new OlmSpecials();v=view();v.oneTileFalling=true;v.tickWalking=true;v.reachable.clear();v.reachable.add(c(2,0));v.reachable.add(c(1,0));v.reachable.add(c(0,1));v.hazards.add(new OlmSpecials.Hazard(v.player,OlmSpecials.HazardKind.FALLING,0));v.hazards.add(new OlmSpecials.Hazard(c(1,0),OlmSpecials.HazardKind.ELECTRIC,0));OlmSpecials.Choice single=p.choose(v);check(single.kind==OlmSpecials.Kind.MOVE&&single.cell.equals(c(0,1))&&single.cell.distance(v.player)==1,"falling dodge stays adjacent and rejects electric wall even with longer reachable destinations");v.reachable.remove(c(0,1));check(p.choose(v).kind==OlmSpecials.Kind.HOLD,"blocked single-tile exits do not turn into a longer run or cross electricity");v.reachable.add(c(-1,0));check(p.choose(v).cell.equals(c(-1,0)),"updated wall state permits a different adjacent escape");
  p=new OlmSpecials();v=view();v.hazards.add(new OlmSpecials.Hazard(v.player,OlmSpecials.HazardKind.FALLING,0));v.forbidden.add(c(1,0));check(!p.safe(c(1,0),v)&&p.choose(v).cell.equals(c(0,1)),"the two post-entry barrier rows can never become a dodge destination");
  v=view();v.hazards.add(new OlmSpecials.Hazard(c(5,5),OlmSpecials.HazardKind.UNDERFOOT,0));check(!OlmSpecials.immediateDanger(v),"a remote spawning ground crystal does not cancel travel or combat");v.hazards.add(new OlmSpecials.Hazard(v.player,OlmSpecials.HazardKind.UNDERFOOT,0));check(OlmSpecials.immediateDanger(v),"a ground crystal under the player still requires an immediate dodge");
  check(!OlmMechanicAdapter.pastEntryRows(c(0,1),c(0,0),c(0,10))&&!OlmMechanicAdapter.pastEntryRows(c(0,2),c(0,0),c(0,10))&&OlmMechanicAdapter.pastEntryRows(c(0,3),c(0,0),c(0,10)),"barrier rows arm only after the player has crossed and settled three tiles inside");
  p=new OlmSpecials();v=view();v.rangeLocked=true;v.hazards.add(new OlmSpecials.Hazard(v.player,OlmSpecials.HazardKind.FALLING,0));v.reachable.clear();v.reachable.add(c(-1,0));v.reachable.add(c(1,0));v.attackDistance.put(c(-1,0),3);v.attackDistance.put(c(1,0),1);check(p.choose(v).cell.equals(c(1,0)),"when no adjacent melee tile is safe, falling-crystal movement stays as close to melee range as possible");
  v=view();v.hazards.add(new OlmSpecials.Hazard(c(1,0),OlmSpecials.HazardKind.ELECTRIC,0));check(OlmMechanicAdapter.electricCrossing(v,c(0,0),c(1,1)),"diagonal crystal dodge cannot clip an electric wall corner");check(!OlmMechanicAdapter.electricCrossing(v,c(0,0),c(-1,1)),"diagonal away from electricity remains available");
  p=new OlmSpecials();v=view();v.stopAttack=true;v.target=c(1,0);v.reachable.add(c(-1,0));check(p.choose(v).kind==OlmSpecials.Kind.CANCEL_ATTACK&&p.choose(v).cell.equals(v.player),"healing cancels melee autoattack without an unnecessary retreat");
  p=new OlmSpecials();v=view();v.oneTileFalling=true;v.hazards.add(new OlmSpecials.Hazard(v.player,OlmSpecials.HazardKind.FALLING,2));check(p.choose(v).kind==OlmSpecials.Kind.MOVE&&p.choose(v).cell.distance(v.player)==1,"larger crystal buffer escapes by adjacent progress rather than holding or a multi-tile request");v.hazards.clear();v.hazards.add(new OlmSpecials.Hazard(v.player,OlmSpecials.HazardKind.ELECTRIC,1));check(p.choose(v).kind==OlmSpecials.Kind.MOVE&&p.choose(v).cell.distance(v.player)==1,"electric wall overlapping player permits a single outward escape step");
  p=new OlmSpecials();v=view();v.oneTileFalling=true;v.stopAttack=true;v.hazards.add(new OlmSpecials.Hazard(v.player,OlmSpecials.HazardKind.UNDERFOOT,0));for(int x=-1;x<=1;x++){v.walls.add(c(x,1));v.walls.add(c(x,-1));}breakWall=p.choose(v);check(breakWall.kind==OlmSpecials.Kind.BREAK_WALL&&p.fireEscapePending(),"flame gap takes priority over crystals and attack cancellation");check(p.choose(v).kind==OlmSpecials.Kind.BREAK_WALL,"rejected UI slot does not impose a false wall cooldown");p.wallRequested(v.tick);v.walls.remove(breakWall.cell);v.reachable.clear();v.reachable.add(c(0,4));check(p.choose(v).cell.equals(c(0,4)),"unrelated falling signals cannot restrict flame escape to one tile");v.player=c(0,2);p.refreshFire(v);check(p.fireEscapePending(),"flame priority remains until two-tile outside clearance");v.player=c(0,3);p.refreshFire(v);check(!p.fireEscapePending()&&p.holdingOutside(),"observed outside position releases exclusive escape priority");
  OlmCamera.Zoom zoom=new OlmCamera.Zoom();check(zoom.due(1,500,false),"camera requests initial wide view");zoom.sent(1,500);check(!zoom.due(2,500,false),"zoom waits for observed response");for(int i=1;i<=3;i++){check(zoom.due(1+i*8,500,false),"zoom checks native boundary");zoom.sent(1+i*8,500);}check(!zoom.due(100,500,false),"unchanged native zoom boundary stops wheel spam");check(zoom.due(101,400,false),"manual zoom change triggers zoom-out maintenance");check(OlmCamera.yaw(0,1)==0&&OlmCamera.yaw(1,0)==1536&&OlmCamera.difference(10,2040)==18,"camera orientation wraps by the short direction");
  java.util.Map<String,Object> cameraValues=new java.util.HashMap<>();cameraValues.put("getHealthRatio",10);net.runelite.api.NPC liveBoss=ChambersTests.fake(net.runelite.api.NPC.class,cameraValues);check(OlmCamera.active(true,true,false,liveBoss),"camera runs only for a live Olm during entered combat");check(!OlmCamera.active(true,true,true,liveBoss)&&!OlmCamera.active(true,false,false,liveBoss)&&!OlmCamera.active(true,true,false,null),"looting, entry and missing heads cannot trigger camera movement");cameraValues.put("isDead",true);check(!OlmCamera.active(true,true,false,liveBoss),"head death immediately disables camera");check(OlmCamera.turnKey(true,200,1000,true)==0,"visible Olm never causes unnecessary pitch or yaw changes");check(OlmCamera.turnKey(false,320,200,true)==java.awt.event.KeyEvent.VK_LEFT&&OlmCamera.turnKey(false,320,200,false)==java.awt.event.KeyEvent.VK_RIGHT,"observed camera response can correct turn direction");
  java.awt.Canvas inputCanvas=new java.awt.Canvas();java.util.concurrent.atomic.AtomicInteger delivered=new java.util.concurrent.atomic.AtomicInteger();inputCanvas.addKeyListener(new java.awt.event.KeyAdapter(){public void keyPressed(java.awt.event.KeyEvent e){if(e.getKeyCode()==java.awt.event.KeyEvent.VK_LEFT&&e.getKeyLocation()==java.awt.event.KeyEvent.KEY_LOCATION_STANDARD)delivered.incrementAndGet();}public void keyReleased(java.awt.event.KeyEvent e){delivered.incrementAndGet();}});try{javax.swing.SwingUtilities.invokeAndWait(()->{OlmCamera.key(inputCanvas,java.awt.event.KeyEvent.KEY_PRESSED,java.awt.event.KeyEvent.VK_LEFT);OlmCamera.key(inputCanvas,java.awt.event.KeyEvent.KEY_RELEASED,java.awt.event.KeyEvent.VK_LEFT);});}catch(Exception e){throw new AssertionError(e);}check(delivered.get()==2,"camera key press and release reach canvas listeners through the focus manager");
  System.out.println("Olm special checks passed: orb colours, crystal avoidance, real-gap escape, outside hold, attack opportunities, online movement correction and explicit learning persistence. Synthetic states only; no live inputs.");
 }
